// CSD_RATIONALE_BEGIN
// SQL-generation CSD for the Spider dataset.
// Output contract: exactly one line of the form "SQL: <<YOUR QUERY>>".
// Strategy:
//   1. Append task guidance reminding the model to emit "SQL: <<" before the query.
//   2. Free-generate until "<<" is observed in the output (the model emits "SQL: " then "<<").
//   3. Once inside the constrained span, use AdaptiveConstrainedStep with
//      validTokenGroups (schema tokens) boosted to steer toward schema-grounded
//      SQL tokens. CloseSpanIfComplete closes the span once the parser accepts
//      the complete SQL expression.
//   4. After the span closes, any remaining budget is spent with a final
//      UnconstrainedStep to let the model emit EOS naturally.
// State tracked:
//   - insideConstrainedOut / currentConstrainedOut: constrained span progress.
//   - steps: token budget consumed (drives cost and loop termination).
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity invariant:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//   Branch A (outside span, UnconstrainedStep):
//     If next != "<<", insideConstrainedOut stays false, implication vacuous.
//     If next == "<<", we set currentConstrainedOut := [], which is valid by
//     precondition parser.IsValidPrefix([]).
//   Branch B (inside span, CloseSpanIfComplete):
//     If closed == true, insideConstrainedOut becomes false, implication vacuous,
//     and currentConstrainedOut is set to [] by the helper contract.
//     If closed == false, state is unchanged, invariant holds by induction.
//   Branch C (inside span, AdaptiveConstrainedStep + AppendConstrainedToken):
//     AdaptiveConstrainedStep returns either EOS or a parser-valid next token
//     (hard-mask guarantees this). AppendConstrainedToken extends
//     currentConstrainedOut by that token, which by parser contract keeps
//     parser.IsValidPrefix(currentConstrainedOut) true.
//   Branch D (outside span after close, UnconstrainedStep):
//     insideConstrainedOut is false, implication is vacuous throughout.
//
// progress invariant:
//   |generated| <= |generatedPrefix| + steps
//   Branch A: one UnconstrainedStep consumes 1 step and appends at most 1 token.
//   Branch B (closed): CloseSpanIfComplete costs +1 step and appends ">>"
//     (one token), so generated grows by 1 and steps grows by 1.
//   Branch B (not closed): same cost (+1), no token appended to generated here
//     (token appended in branch C after the CloseSpanIfComplete no-op), so
//     generated length is unchanged while steps grows; bound still holds.
//   Branch C: AdaptiveConstrainedStep costs +1 step, AppendConstrainedToken
//     appends exactly 1 token at +0 cost; net: +1 step, +1 token. Bound holds.
//   Branch D: UnconstrainedStep costs +1 step, appends at most 1 token.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance := "Output exactly one SQL query in the form: SQL: <<SELECT ...>>. Use only the schema tables and columns. No explanation, no markdown, no extra text.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if next == "<<" {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else {
    var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    steps := steps + 1;
    if closed {
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
    } else {
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, 16, eosToken
      );
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

cost := steps;

// CSD_RATIONALE_BEGIN
// SQL-generation CSD for Spider dataset.
// Output contract: "SQL: <<YOUR QUERY>>"
//
// Key diagnosis from attempt 1:
//   - Only 11/300 examples had visible "<<"; 297/300 had no complete visible span.
//   - The model was emitting ">>" as a raw token in free generation, confusing
//     the span tracker, and the constrained phase barely ran (avg 34 tokens/example).
//   - The primary failure mode (179/192 wrong) was: syntax_valid but extracted
//     from text_fallback (not from the constrained span), with zero visible spans.
//     This means the model was generating valid SQL freely but NOT inside "<<>>".
//
// Root cause: The free-generation phase was consuming almost all the budget
//   before "<<" appeared (or never emitting "<<" at all). The model's natural
//   output is "SQL: SELECT ..." without the "<<" delimiter, so the constrained
//   phase never activates.
//
// Fix: Force the constrained span open immediately using OpenConstrainedSpan,
//   THEN generate the SQL under full parser control. Prepend "SQL: " as guidance
//   tokens via the task guidance, then open the span and use GenerateWithManagedSpan
//   (or a tight constrained loop) for the entire SQL body.
//
// Revised strategy:
//   1. Append strong task guidance specifying the exact output format.
//   2. Use GenerateWithPrefixAndManagedSpan with prefixBudget = 10 to allow the
//      model to emit "SQL: " (a few tokens) before forcing the span open.
//      This ensures "<<" appears early and the SQL is fully constrained.
//   3. Use AdaptiveConstrainedStep with schema token groups boosted inside the span.
//   4. CloseSpanWithinBudget handles span closure with remaining budget.
//
// The key insight: don't wait for the model to emit "<<" naturally—force it
// after a short prefix budget so the constrained phase actually runs.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity invariant:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   GenerateWithPrefixAndManagedSpan discharges all internal invariants itself.
//   On return, it guarantees:
//     !insideConstrainedOut ==> currentConstrainedOut == []
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//   So the invariant holds unconditionally after the call.
//
// progress invariant:
//   |generated| <= |generatedPrefix| + maxSteps
//
//   GenerateWithPrefixAndManagedSpan costs at most +maxSteps by its postcondition.
//   We set cost := maxSteps as an upper bound.
//   The progress postcondition is also discharged by the helper's own contract:
//     |generated| <= |generatedPrefix| + maxSteps.
//
// The "maxSteps == 0 || cost > 0 || ..." postcondition:
//   When maxSteps > 0, GenerateWithPrefixAndManagedSpan takes at least one step
//   (it calls OpenConstrainedSpan if prefixBudget is exhausted without "<<"),
//   so cost > 0 whenever maxSteps > 0.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance := "Output ONLY: SQL: <<SELECT ...>> where the query uses only schema tables/columns. No explanation. The << and >> delimiters are required. Example: SQL: <<SELECT col FROM tbl WHERE cond>>";
helpers.AppendTaskGuidance(lm, guidance);

if maxSteps == 0 {
  cost := 0;
} else {
  // Use a short prefix budget (up to 8 tokens) to let the model emit "SQL: "
  // then force the constrained span open. The remaining budget goes to SQL generation.
  var prefixBudget: nat := 8;
  if prefixBudget > maxSteps {
    prefixBudget := maxSteps;
  }

  var g, ic, cc := helpers.GenerateWithPrefixAndManagedSpan(
    lm, parser, prompt, generated, insideConstrainedOut, currentConstrainedOut,
    maxSteps, prefixBudget, validTokenGroups, 5.0, 20, eosToken
  );
  generated := g;
  insideConstrainedOut := ic;
  currentConstrainedOut := cc;
  cost := maxSteps;
}

// CSD_RATIONALE_BEGIN
// SQL-generation CSD for Spider dataset - Attempt 3.
//
// Key diagnosis from attempts 1 & 2:
//   - mode_A persists: 176/300 examples wrong, all with "zero_visible_spans",
//     "answer_source: text_fallback", "contains_delimiters: yes" but
//     "visible_delimiters: no".
//   - Generated tokens/example is tiny: avg 8.78, median 7.00.
//   - "Examples with unmatched visible close: 293/300" - the model is emitting
//     ">>" in the constrained output (as part of the SQL grammar completion),
//     which is being interpreted as a close delimiter, but "<<" was never
//     visible in the free-prefix phase.
//
// Root cause analysis:
//   The GenerateWithPrefixAndManagedSpan helper uses "<<" as the observed open
//   delimiter during the unconstrained prefix phase. The model's natural output
//   is "SQL: SELECT ..." without "<<". After prefixBudget=8 steps without
//   observing "<<", OpenConstrainedSpan is called to force "<<" into the output.
//   BUT: the diagnostic says 0/300 examples have visible "<<". This means
//   OpenConstrainedSpan IS being called but the span is being classified as
//   "hidden" (the constrained activity shows 300/300 with activity, and
//   CloseConstrainedSpan was called 293/300 times).
//
//   The evaluator says "visible_delimiters: no" and "zero_visible_spans".
//   The key insight: the evaluator sees "contains_delimiters: yes" but
//   "visible_delimiters: no". This means the CSD IS placing content in a
//   hidden span (task-native surface) rather than a visible "<<...>>" span.
//   GenerateWithPrefixAndManagedSpan uses the task-native surface for "hidden
//   constrained chunks" - it does NOT emit visible "<<" and ">>" tokens.
//
//   The task contract explicitly requires "SQL: <<YOUR QUERY>>" format with
//   VISIBLE delimiters. The evaluator expects visible "<<" and ">>" tokens
//   in the generated output.
//
// Fix: Manually implement the loop:
//   1. Use UnconstrainedStep for a short prefix to let the model emit "SQL: "
//   2. Explicitly call OpenConstrainedSpan to force VISIBLE "<<" into output
//   3. Use ConstrainedStep in a tight loop for the SQL body
//   4. Close with CloseConstrainedSpan when complete, or CloseSpanWithinBudget
//
// The critical difference: OpenConstrainedSpan emits VISIBLE "<<" into generated,
// which is what the evaluator needs to see. The helper-managed loops use hidden
// span infrastructure that doesn't emit visible "<<".
//
// Token budget: maxSteps=900, stepTokenBudget=1.
// Strategy: spend up to 10 steps on free prefix (for "SQL: "), then force open
// visible span, then spend remaining budget on constrained SQL generation.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity invariant:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Phase 1 (free prefix): Only flips insideConstrainedOut to true if "<<"
//   is naturally observed; we set currentConstrainedOut := [] which is valid
//   (parser.IsValidPrefix([]) is a precondition). Otherwise insideConstrainedOut
//   remains false, making the implication vacuous.
//
//   Phase 2 (force open): OpenConstrainedSpan sets insideConstrainedOut := true
//   and currentConstrainedOut := [], which is valid by precondition.
//
//   Phase 3 (constrained loop): Each iteration either:
//     (a) Closes the span via CloseConstrainedSpan: insideConstrainedOut becomes
//         false, implication vacuous.
//     (b) Takes AdaptiveConstrainedStep returning EOS -> break, implication
//         preserved since we don't change constrained state.
//     (c) Takes AdaptiveConstrainedStep returning a valid token, then
//         AppendConstrainedToken extends currentConstrainedOut. Since the step
//         is parser-controlled, AppendConstrainedToken preserves IsValidPrefix.
//
// progress invariant:
//   |generated| <= |generatedPrefix| + steps
//
//   Phase 1: Each iteration increments steps by 1 and appends at most 1 token
//   to generated (or 0 on EOS), so |generated| <= |generatedPrefix| + steps.
//
//   Phase 2: OpenConstrainedSpan appends 1 token ("<<") and costs 1 step.
//   steps is incremented by 1, so invariant preserved.
//
//   Phase 3: Each iteration increments steps by 1. CloseConstrainedSpan appends
//   ">>" (1 token, 1 step). AdaptiveConstrainedStep either returns EOS (no
//   append) or a valid token; AppendConstrainedToken appends 1 token but costs
//   0 steps (token was already counted). So each iteration: steps+1, generated+1.
//   Invariant preserved.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance := "Output exactly: SQL: <<query>> where query is valid SQL using only schema tables and columns. The << and >> delimiters are mandatory. No markdown, no explanation.";
helpers.AppendTaskGuidance(lm, guidance);

if maxSteps == 0 {
  cost := 0;
} else {
  var steps: nat := 0;

  // Phase 1: Short unconstrained prefix to let model emit "SQL: "
  // Budget: up to 12 steps. Stop early if "<<" is observed or EOS.
  var prefixBudget: nat := 12;
  var hitEos: bool := false;

  while steps < prefixBudget && steps < maxSteps && !insideConstrainedOut && !hitEos
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases prefixBudget - steps
  {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      hitEos := true;
    } else {
      generated := generated + [next];
      if next == "<<" {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  }

  // Phase 2: If not yet inside constrained span and not EOS, force open visible span
  if !insideConstrainedOut && !hitEos && steps < maxSteps {
    var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
    generated := og;
    insideConstrainedOut := oi;
    currentConstrainedOut := oc;
    steps := steps + 1;
  }

  // Phase 3: Constrained SQL generation inside visible span
  while steps < maxSteps && insideConstrainedOut
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases maxSteps - steps
  {
    if parser.IsCompletePrefix(currentConstrainedOut) {
      // Close the span with visible ">>"
      var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else {
      // Generate next constrained token
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 5.0, 20, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        // Try to close with remaining budget
        var closeBudget := maxSteps - steps;
        if closeBudget > 0 {
          var cg, ci, cc := helpers.CloseSpanWithinBudget(
            lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
          );
          generated := cg;
          insideConstrainedOut := ci;
          currentConstrainedOut := cc;
          steps := maxSteps;
        }
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }

  // If span still open and budget remains, try to close it
  if insideConstrainedOut && steps < maxSteps {
    var closeBudget := maxSteps - steps;
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
  }

  cost := steps;
}

// CSD_RATIONALE_BEGIN
// Diagnosis of mode_A (167/300 wrong):
//   "visible_delimiters: no" and "zero_visible_spans: yes" despite "contains_delimiters: yes".
//   This means "<<" is never appearing in `generated` as a visible token.
//   The diagnostic shows OpenConstrainedSpan IS being called (294 CloseConstrainedSpan calls),
//   but "Examples with visible <<: 0/300".
//
// Root cause: OpenConstrainedSpan appends "<<" to `generated`, but the evaluator
// is NOT seeing visible "<<" in the output. The evaluator's span extraction appears
// to look at the *final* generated sequence and find visible "<<" tokens. But 
// "answer_source: text_fallback" for 0/300 (all answers come from somewhere), 
// and "Span usefulness: valid_nonfinal_spans_only 300/300" means the SQL is being
// extracted from a constrained span but the span is classified as "nonfinal" 
// (because ">>" appears in the constrained content itself, ending the span early).
//
// Key insight from rollouts:
//   - The SQL grammar apparently emits ">>" as part of the constrained output 
//     (the parser's completion triggers ">>" emission by CloseConstrainedSpan).
//   - But "<<" is never visible because it was added to `generated` but the
//     evaluator sees the raw output differently.
//
// Wait - re-reading: "Examples with visible <<: 0/300" but OpenConstrainedSpan
// was called ~300 times. This is contradictory unless OpenConstrainedSpan's "<<"
// is being treated as a hidden delimiter, not a visible token in the output stream.
//
// Actually reading the API more carefully:
//   OpenConstrainedSpan "appends visible '<<'" - it should be visible.
//   But the diagnostic shows 0 visible "<<". 
//
// NEW HYPOTHESIS: The constrained prompt computation is wrong. When we do:
//   constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|]
// After OpenConstrainedSpan adds "<<", generated has "<<" at the end (with
// currentConstrainedOut = []), so generated[..|generated| - 0] = generated (full),
// which includes "<<". The constrained generation then generates SQL tokens.
// CloseConstrainedSpan appends ">>" to generated.
// So the final generated sequence IS: [..., "<<", "SELECT", ..., ">>"].
//
// But evaluator says "visible <<: 0/300". Perhaps the test harness strips
// the constrained-span delimiter tokens from visible output? 
//
// ALTERNATIVE: The SQL grammar itself contains ">>" as a valid completion token,
// so when parser.IsCompletePrefix fires, the current constrained contains the SQL
// without ">>", and CloseConstrainedSpan appends ">>". BUT the OPEN "<<" was
// appended by OpenConstrainedSpan at step (say) 12 or 13. The issue is that
// "SQL:" prefix takes ~3-4 tokens ("SQL", ":", " ") and then "<<" is forced,
// so generated looks like ["SQL", ":", " ", "<<", "SELECT", ...].
//
// Wait - the 3rd rollout shows "SELECT a.address_id...FROM addresses>>" as the 
// STRATEGY EXTRACTED output. This means the evaluator DID extract the SQL, but
// the ">>" at the end is from CloseConstrainedSpan being called on a parser-complete
// prefix that included the ">>" in the SQL itself. The extracted query contains ">>"!
//
// CORE ISSUE: The SQL parser completes before getting a full/correct query
// because the grammar is quite permissive. The model generates partial queries,
// the parser says IsCompletePrefix, and we close too early.
//
// STRATEGY CHANGE:
// 1. Keep using visible "<<" and ">>" (the evaluator needs them)
// 2. The real problem is query quality - we close too early with incomplete SQL
// 3. Use SafeRepetitionPenaltyStep to avoid token repetition
// 4. Use SafeTemperatureConstrainedStep with lower temperature (0.7) to be 
//    more deterministic and follow model's distribution more faithfully
// 5. Do NOT close on first IsCompletePrefix - continue generating until the
//    SQL is more complete (budget-aware)
// 6. Only close when near budget OR when a strong completion signal exists
//
// The key insight from rollouts: the model generates good SQL naturally but
// gets truncated. The constrained generation is cutting off early because
// the SQL grammar recognizes "SELECT column FROM table" as complete even
// without WHERE/JOIN/ORDER BY clauses. We need to let the model generate
// more complete queries.
//
// APPROACH: Use SafeRepetitionPenaltyStep to avoid loops, and delay span
// closure until we've used a substantial portion of budget OR the LM itself
// signals EOS. Reserve space for close at end.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity invariant:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Phase 1 (free prefix, up to 8 steps): UnconstrainedStep returns any token.
//   If next == "<<", we set currentConstrainedOut := [] which satisfies
//   parser.IsValidPrefix([]) by precondition. Otherwise insideConstrainedOut
//   stays false, making implication vacuous.
//
//   Phase 2 (force open): OpenConstrainedSpan sets insideConstrainedOut := true
//   and currentConstrainedOut := [], valid by precondition. Steps incremented.
//
//   Phase 3 (constrained loop): Each iteration either:
//     (a) Closes via CloseConstrainedSpan when IsCompletePrefix holds:
//         insideConstrainedOut becomes false, implication vacuous.
//     (b) Returns EOS from constrained step: insideConstrainedOut unchanged,
//         implication holds from loop invariant. Then break.
//     (c) Returns valid token from SafeRepetitionPenaltyStep:
//         AppendConstrainedToken extends currentConstrainedOut preserving
//         IsValidPrefix (the step guarantees parser validity).
//
// progress invariant:
//   |generated| <= |generatedPrefix| + steps
//
//   Phase 1: Each iteration: steps+1, generated grows by at most 1.
//   Phase 2: OpenConstrainedSpan: generated grows by 1 ("<<"), steps+1.
//   Phase 3 loop body: steps+1 per iteration (from constrained step or close).
//   AppendConstrainedToken: grows generated by 1, no step cost (already counted).
//   CloseConstrainedSpan: grows generated by 1 (">>"), 1 step already counted.
//   Final CloseSpanWithinBudget: uses closeBudget = maxSteps - steps, so
//     |generated| grows by at most closeBudget = maxSteps - steps,
//     total |generated| <= |generatedPrefix| + maxSteps.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance := "Generate a valid SQL query. Output format: SQL: <<query>>. Use only schema tables and columns. Write complete SQL with all necessary JOINs, WHERE, GROUP BY, ORDER BY, LIMIT clauses as needed.";
helpers.AppendTaskGuidance(lm, guidance);

if maxSteps == 0 {
  cost := 0;
} else {
  var steps: nat := 0;
  var hitEos: bool := false;

  // Phase 1: Short unconstrained prefix (up to 6 steps) to let model emit "SQL: "
  var prefixBudget: nat := 6;

  while steps < prefixBudget && steps < maxSteps && !insideConstrainedOut && !hitEos
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases prefixBudget - steps
  {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      hitEos := true;
    } else {
      generated := generated + [next];
      if next == "<<" {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  }

  // Phase 2: Force open visible span if not already inside one
  if !insideConstrainedOut && !hitEos && steps < maxSteps {
    var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
    generated := og;
    insideConstrainedOut := oi;
    currentConstrainedOut := oc;
    steps := steps + 1;
  }

  // Phase 3: Constrained SQL generation
  // Strategy: Don't close on first IsCompletePrefix. Instead, keep generating
  // until EOS is signaled OR we're within 2 steps of budget.
  // Use SafeRepetitionPenaltyStep to avoid repetitive token output.
  // Only close when the model signals EOS or budget is nearly exhausted.
  var closedSpan: bool := false;

  while steps < maxSteps && insideConstrainedOut && !closedSpan
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases maxSteps - steps
  {
    // Reserve at least 1 step for closing
    var remainingBudget := maxSteps - steps;

    if remainingBudget <= 1 {
      // Must close now
      if parser.IsCompletePrefix(currentConstrainedOut) {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
        closedSpan := true;
      } else {
        // Force close with whatever budget we have
        var cg, ci, cc := helpers.CloseSpanWithinBudget(
          lm, parser, prompt, generated, currentConstrainedOut, eosToken, remainingBudget
        );
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := maxSteps;
        closedSpan := true;
      }
    } else {
      // Generate next token with repetition penalty to encourage diverse SQL
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.SafeRepetitionPenaltyStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, generated, 1.5, eosToken
      );
      steps := steps + 1;

      if next == eosToken {
        // Model wants to stop - close the span if complete, else use budget
        if parser.IsCompletePrefix(currentConstrainedOut) {
